
--** total number of orders in each city
SELECT city , Count(*) AS total_orders FROM orders GROUP BY city;

--* total revenue generated by each order status
SELECT status , SUM(amount) AS revenue FROM orders GROUP BY status;

--* average order amount for each city
SELECT city , AVG(amount) AS avg_amount FROM orders GROUP BY city;

--*total revenue generated by each customer
SELECT customer_id , SUM(amount) AS total_revenue FROM orders GROUP BY customer_id;

--* number of Completed orders in each city
SELECT city , COUNT(*) AS completed_orders FROM orders WHERE status = "Completed" GROUP BY city;

--* Total number of orders ,Total revenue ,Average order amount ,Highest order amount
SELECT 
    city ,
    COUNT(*) AS total_orders,
    SUM(amount) AS total_revenue,
    AVG(amount) AS avg_amount,
    MAX(amount) AS highest_amount 
FROM orders
GROUP BY city ;


--* total revenue for each city, but include only orders with an amount greater than ₹500.
SELECT city , SUM (amount) from orders WHERE amount > 500 GROUP BY city  ;

--* number of orders placed by each customer, but consider only Completed orders.
SELECT customer_id , count(*) AS total_completed_orders FROM orders WHERE status = 'Completed' GROUP BY customer_id;

--* Total number of orders ,Total revenue ,Average order amount (city status combination)
SELECT city , status , COUNT(*) AS total_orders , SUM(amount) AS total_revenue, AVG(amount) AS avg_amount FROM orders GROUP BY city,status;